function questionKeyword(id){const k=QUESTION_KEYWORDS[id];return k?(k[state.lang]||k.en):''}
function jumpTargetForProblem(id){const p=problemBank[id];if(!p)return null;const preferred=sections?.find?.(s=>s.id===p.section);const has=(s)=>((PRACTICE_POOLS[s.id]?.[p.level]||[]).includes(id));if(preferred&&has(preferred))return preferred;return sections?.find?.(has)||preferred||null}
