const OBSERVATIONS = {
  logrange:{en:'The restricted domain matters as much as the parabola. Count intersections with the horizontal level only on the allowed interval.',id:'Domain terbatas sama pentingnya dengan parabolanya. Hitung titik potong dengan garis horizontal hanya pada interval yang diperbolehkan.'},
  family:{en:'A change in root count occurs when crossing changes into touching. The graph suggests tangency; calculus must locate it exactly.',id:'Jumlah akar berubah ketika kondisi memotong berubah menjadi menyinggung. Grafik memberi petunjuk tentang titik singgung; kalkulus menentukan nilainya secara eksak.'},
  generalize:{en:'Changing the base changes the exponential growth rate, so the transition value for k must change too. Compare values and slopes at tangency.',id:'Mengubah basis mengubah laju pertumbuhan eksponensial, jadi nilai transisi k juga berubah. Bandingkan nilai fungsi dan gradien pada saat menyinggung.'},
  fixed:{en:'Fixed points are intersections with y=x. The threshold is a tangency event, so value and slope conditions must hold together.',id:'Titik tetap adalah titik potong dengan y=x. Ambangnya terjadi saat menyinggung, sehingga syarat nilai fungsi dan gradien harus berlaku bersamaan.'},
  inequality:{en:'The inequality becomes a minimum problem after moving everything to one side. A global minimum of zero proves the claim.',id:'Pertidaksamaan berubah menjadi masalah minimum setelah semua suku dipindahkan ke satu sisi. Minimum global bernilai nol membuktikan klaim.'},
  models:{en:'For exponential models, ratios often eliminate an unknown scale factor. Equal time spacing can expose a constant multiplicative change.',id:'Pada model eksponensial, rasio sering menghilangkan faktor skala yang belum diketahui. Selang waktu yang sama dapat menampakkan faktor perubahan yang konstan.'},
  inverse:{en:'For a strictly increasing one-to-one function, intersections with its inverse must be fixed points on y=x.',id:'Untuk fungsi satu-satu yang naik tegas, titik potong dengan inversnya harus berupa titik tetap pada y=x.'}
};

