  const choices=[{value:'yes',label:p2bi('Yes — two observations determine all three parameters','Ya — dua observasi menentukan ketiga parameter')},{value:'no',label:p2bi('No — a family of shifted models can fit','Tidak — ada keluarga model bergeser yang dapat cocok')}];
