 return `<div class="visual-window-backdrop" data-visual-backdrop><section class="visual-window-modal" role="dialog" aria-modal="true" aria-labelledby="visualWindowTitle"><div class="visual-window-head"><div><div class="eyebrow">${tx('visualWindow')}</div><h2 id="visualWindowTitle">${tx('visualWindowTitle')}</h2></div><button class="visual-window-close" type="button" data-visual-close aria-label="${tx('close')}">×</button></div><div class="visual-window-tabs" role="tablist" aria-label="${state.lang==='en'?'Reference type':'Jenis referensi'}"><button type="button" role="tab" data-visual-tab="graph" aria-selected="${graphTab}" class="${graphTab?'active':''}">${tx('graphTab')}</button><button type="button" role="tab" data-visual-tab="toolkit" aria-selected="${!graphTab}" class="${!graphTab?'active':''}">${tx('logToolkitTab')}</button></div>${body}</section></div>`;
